 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); cells = []
            while stack:
                x, y = stack.pop(); cells.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != 0 and (nx, ny) not in seen:
                            seen.add((nx, ny)); stack.append((nx, ny))
            comps.append(cells)
    # The target is the smallest of the substantial connected shapes.
    cells = min((p for p in comps if len(p) > 1), key=len)
    r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
    c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
    S = set(cells)
    return [[grid[r][c] if (r,c) in S else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
