 "content": "def transform(grid):
    # Isolate 8-connected objects and select the most dense shape that matches
    # the medium-size symbols in the demonstrations.
    h, w = len(grid), len(grid[0])
    seen, objs = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); cells = []
            while stack:
                x, y = stack.pop(); cells.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        a, b = x + dx, y + dy
                        if 0 <= a < h and 0 <= b < w and grid[a][b] and (a, b) not in seen:
                            seen.add((a, b)); stack.append((a, b))
            objs.append(cells)
    def score(cells):
        r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
        c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
        return (len(cells) / ((r1-r0+1)*(c1-c0+1)), -len(cells))
    cells = max((p for p in objs if len(p) > 5), key=score)
    r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
    c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
    members = set(cells)
    return [[grid[r][c] if (r,c) in members else 0 for c in range(c0,c1+1)]
            for r in range(r0,r1+1)]
